def reverse_string(s):
    return ''.join(reversed(s))

# Using a loop
def reverse_string(s):
    result = ''
    for char in s:
        result = char + result
    return result

# Using recursion
def reverse_string(s):
    if len(s) <= 1:
        return s
    return s[-1] + reverse_string(s[:-1])

def fibonacci(n):
    """Recursive implementation (less efficient for large n)"""
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

def flatten_list(nested_list):
    result = []
    for item in nested_list:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

def group_anagrams(strs):
    """
    Groups anagrams together from a list of strings.

    Args:
        strs: List of strings to group

    Returns:
        List of lists, where each inner list contains anagrams
    """
    if not strs:
        return []

    anagram_groups = {}

    for word in strs:
        # Create signature by sorting characters
        signature = ''.join(sorted(word))

        if signature not in anagram_groups:
            anagram_groups[signature] = []

        anagram_groups[signature].append(word)

    # Convert to list of lists
    return list(anagram_groups.values())

