def merge_sorted_lists(list1, list2):
    result = []
    i = j = 0

    # Compare elements from both lists and add the smaller one
    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            result.append(list1[i])
            i += 1
        else:
            result.append(list2[j])
            j += 1

    # Add remaining elements from list1 (if any)
    while i < len(list1):
        result.append(list1[i])
        i += 1

    # Add remaining elements from list2 (if any)
    while j < len(list2):
        result.append(list2[j])
        j += 1

    return result

def find_max(numbers):
    result = numbers[0]
    for i in range(len(numbers)):
        if numbers[i] > result:
            result = numbers[i]
    return result

def binary_search(sorted_list, target):
    left = 0
    right = len(sorted_list) - 1

    while left <= right:
        mid = (left + right) // 2
        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def flatten_list(nested_list):
    """
    Flattens a nested list using a generator approach.
    More memory efficient for large nested structures.
    """
    def _flatten_generator(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten_generator(item)
            else:
                yield item

    return list(_flatten_generator(nested_list))

def group_anagrams(strs):
    from collections import defaultdict

    if not strs:
        return []

    groups = defaultdict(list)
    for word in strs:
        key = ''.join(sorted(word))
        groups[key].append(word)

    return list(groups.values())

def rotate_matrix(matrix):
    if not matrix or not matrix[0]:
        return matrix if matrix == [[]] else []

    return [[matrix[row][col] for row in range(len(matrix) - 1, -1, -1)] 
            for col in range(len(matrix[0]))]

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key in self.cache:
            # Move to end (most recently used)
            self.cache.move_to_end(key)
            return self.cache[key]
        return -1

    def put(self, key, value):
        if key in self.cache:
            # Update and move to end
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            # Check capacity
            if len(self.cache) >= self.capacity:
                # Remove least recently used (first item)
                self.cache.popitem(last=False)
            # Add new item
            self.cache[key] = value
